import{_ as s,o as a,c as t,a5 as i}from"./chunks/framework.BjM_ivYE.js";const b=JSON.parse('{"title":"Image Echo — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/image-echo.md","filePath":"software/sdk/cpp/image-echo.md","lastUpdated":1785817728000}'),o={name:"software/sdk/cpp/image-echo.md"};function n(r,e,l,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="image-echo-—-c-example" tabindex="-1">Image Echo — C++ Example <a class="header-anchor" href="#image-echo-—-c-example" aria-label="Permalink to &quot;Image Echo — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_image_echo.cpp</code></p><p>A minimal, read-only diagnostic that <strong>subscribes to a compressed camera topic</strong> and prints the receive rate, last frame size, and image format once per second. Use it to confirm a camera stream is actually being published and is reachable from your SDK host.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The program:</p><ol><li>Reads the topic name from <code>argv[1]</code> (default <code>rt/rbq/vision/sensor_4/rgb/compressed</code>) and the network interface from <code>argv[2]</code> (default <code>lo</code>).</li><li>Initializes the DDS <code>ChannelFactory</code> on that interface and creates a <code>Subscriber&lt;CompressedImage_&gt;</code>.</li><li>On every received sample, updates a counter plus the last byte size and image format.</li><li>Once per second, prints elapsed time, total samples, the 1-second rate, last frame size, and format.</li><li>Exits cleanly on <code>Ctrl+C</code> (SIGINT/SIGTERM), printing the total sample count.</li></ol><p>It never publishes, so it is safe to run alongside a live robot or the simulator.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>A publisher of the compressed image topic running — the robot&#39;s vision stack, or the MuJoCo simulator with vision (<code>bash scripts/sim.bash --vision</code>).</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_image_echo</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Both arguments are optional:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [topic] [interface]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Arg</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>topic</code></td><td>Compressed image topic to subscribe to</td><td><code>rt/rbq/vision/sensor_4/rgb/compressed</code></td></tr><tr><td><code>interface</code></td><td>CycloneDDS interface</td><td><code>lo</code></td></tr></tbody></table><h3 id="in-the-mujoco-simulator" tabindex="-1">In the MuJoCo simulator <a class="header-anchor" href="#in-the-mujoco-simulator" aria-label="Permalink to &quot;In the MuJoCo simulator&quot;">​</a></h3><p>The simulator publishes on <code>lo</code> — the same default this example uses — so no arguments are needed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # one terminal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # another terminal</span></span></code></pre></div><p>Cameras use <strong>numeric</strong> ids on both the robot and the sim. <code>sensor_4</code> is the <strong>front</strong> camera and <code>sensor_5</code> is the <strong>rear</strong> camera; <code>sensor_0</code>–<code>sensor_3</code> publish only <code>depth</code> and <code>ir</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # front camera</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_5/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # rear camera</span></span></code></pre></div><h3 id="on-a-real-robot-from-another-host" tabindex="-1">On a real robot, from another host <a class="header-anchor" href="#on-a-real-robot-from-another-host" aria-label="Permalink to &quot;On a real robot, from another host&quot;">​</a></h3><p>Pass the interface that reaches the robot as the <strong>second</strong> argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span></code></pre></div><p>The robot-side vision stack has to run on an interface your PC can reach — start it on the robot with <code>bash scripts/RBQ.bash -i &lt;nic&gt;</code>. Both sides must use the <strong>same</strong> interface, otherwise you will see <code>rate=0 Hz</code>.</p><blockquote><p>CycloneDDS logs <code>selected interface &quot;lo&quot; is not multicast-capable: disabling multicast</code> when running on <code>lo</code>. This is expected and harmless: discovery still works between processes on the same host, which is exactly the simulator case. Only cross-host setups need a real NIC.</p></blockquote><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><p>Against the MuJoCo simulator (<code>sim.bash --vision</code>), subscribing to <code>sensor_4</code> (front camera):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_image_echo] subscribed to &#39;rt/rbq/vision/sensor_4/rgb/compressed&#39; on interface &#39;lo&#39;</span></span>
<span class="line"><span>[rbq_image_echo] waiting for samples (Ctrl+C to exit)...</span></span>
<span class="line"><span>[rbq_image_echo] 1.0s  total=15  rate=15 Hz  last=13053 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 2.0s  total=29  rate=14 Hz  last=13080 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 3.0s  total=44  rate=15 Hz  last=13067 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] exiting, total samples = 44</span></span></code></pre></div><p>A steady rate with non-zero byte sizes and <code>fmt=&#39;jpeg&#39;</code> confirms the stream is live. <code>rate=0 Hz</code> means no publisher was found on that topic/interface — check the topic name and the DDS interface.</p>`,31)])])}const m=s(o,[["render",n]]);export{b as __pageData,m as default};
